// Some portions generated by Codex
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.model.MemValueFactory;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class MemoryBlankNodeReferenceLifecycleTest {

	private static final String ID = "memory-reference-lifecycle";
	private static final String QUERY = "ASK { <_:" + ID + "> <urn:lifecycle:p> ?value }";

	@Test
	void preparedReferenceTracksCommitDeleteReinsertAndPersistentReopen(@TempDir Path directory) throws Exception {
		BNode expected = SimpleValueFactory.getInstance().createBNode(ID);
		SailRepository repository = new SailRepository(new MemoryStore(directory.toFile()));
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				MemValueFactory valueFactory = (MemValueFactory) repository.getValueFactory();
				var ask = connection.prepareBooleanQuery(QUERY);
				assertNull(valueFactory.getMemBNode(expected),
						"preparing an absent fixed reference must not intern it");
				assertFalse(ask.evaluate());
				assertNull(valueFactory.getMemBNode(expected),
						"evaluating an absent fixed reference must remain a lookup");

				connection.begin();
				connection.add(expected, SimpleValueFactory.getInstance().createIRI("urn:lifecycle:p"),
						SimpleValueFactory.getInstance().createLiteral("first"));
				connection.commit();
				assertTrue(ask.evaluate(), "a prepared reference must observe the committed matching statement");
				assertEquals(ID, valueFactory.getMemBNode(expected).getID());

				connection.begin();
				connection.remove(expected, SimpleValueFactory.getInstance().createIRI("urn:lifecycle:p"), null);
				connection.commit();
				assertFalse(ask.evaluate(), "deleting the statement must not leave a stale positive reference result");

				connection.begin();
				connection.add(expected, SimpleValueFactory.getInstance().createIRI("urn:lifecycle:p"),
						SimpleValueFactory.getInstance().createLiteral("second"));
				connection.commit();
				assertTrue(ask.evaluate(), "reusing the same lexical ID must restore the exact fixed identity");
			}
		} finally {
			repository.shutDown();
		}

		SailRepository reopened = new SailRepository(new MemoryStore(directory.toFile()));
		reopened.init();
		try {
			try (var connection = reopened.getConnection()) {
				assertTrue(connection.prepareBooleanQuery(QUERY).evaluate());
				var stored = ((MemValueFactory) reopened.getValueFactory()).getMemBNode(expected);
				assertNotNull(stored, "the reopened store must resolve the persisted blank-node identity");
				assertEquals(ID, stored.getID());
				assertEquals(expected, stored);
			}
		} finally {
			reopened.shutDown();
		}
	}
}
